const body = $json.body ?? $json;
const title = (body.film_title ?? body['Film Title'] ?? '').toString().trim();
const story = (body.story ?? body['Story'] ?? '').toString().trim();
if (!title) throw new Error('Film Title is required.');
if (!story || story.length < 20) throw new Error('Story is required (at least 20 characters).');
const slug = (title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60)) || 'untitled-film';

// Collect uploaded reference images from binary properties (names vary by n8n version)
const bin = (items[0] && items[0].binary) ? items[0].binary : {};
const props = Object.keys(bin).sort();
if (!props.length) throw new Error('No reference images were uploaded.');
const refs = [];
for (const prop of props) {
  const meta = bin[prop] ?? {};
  const filename = (meta.filename ?? 'upload.jpg').toString();
  const extRaw = (filename.split('.').pop() ?? 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '');
  const ext = ['jpg', 'jpeg', 'png', 'webp'].includes(extRaw) ? extRaw : 'jpg';
  const buf = await this.helpers.getBinaryDataBuffer(0, prop);
  if (!buf || !buf.length) continue;
  refs.push({ filename, ext, b64: buf.toString('base64') });
}
if (!refs.length) throw new Error('Reference image uploads could not be read.');
if (refs.length > 6) throw new Error('Please upload at most 6 reference images.');

return [{ json: { title, slug, refCount: refs.length, refs } }];
